export interface FaqItem {
  question: string;
  answer: string;
}

export const FAQ_ITEMS: FaqItem[] = [
  {
    question: "What exactly does Boldteq do?",
    answer:
      "Boldteq becomes the delivery team behind your agency.\nWe provide a fully managed design & development backend — including project ownership, QA review, and live request tracking — so you can scale client work without hiring or managing in-house teams.",
  },
  {
    question: "Is Boldteq an agency, a tool, or a staffing service?",
    answer:
      "Neither.\nBoldteq is a delivery infrastructure.\nYou get a dedicated execution team + a delivery system to submit requests, track progress, and manage feedback — all under one subscription.\nNo freelancers. No staff leasing. No chaotic outsourcing.",
  },
  {
    question: "Who is Boldteq built for?",
    answer:
      "Boldteq is built for digital agencies that:\n• want predictable delivery\n• need reliable execution partners\n• are tired of hiring delays or freelancer churn\n• handle ongoing client work\n• care about quality and accountability\nWhether you're early-stage or high-volume, Boldteq adapts to your workflow.",
  },
  {
    question: "What happens after we subscribe?",
    answer:
      "You'll get:\n• onboarding with your delivery owner\n• access to your private delivery dashboard\n• workflow alignment\n• brand standard setup\nThen you start submitting requests.\nDelivery begins immediately.",
  },
  {
    question: "How do we submit and manage work?",
    answer:
      "You submit tasks through your private Boldteq delivery dashboard.\nFrom there you can:\n• create requests\n• track status in real time\n• communicate directly on each task\n• give feedback\n• approve deliveries\nEverything stays organized in one place.",
  },
  {
    question: "Who is responsible for quality and final delivery?",
    answer:
      "Boldteq always takes the ownership for quality and delivery.\nEvery account has a dedicated delivery owner, and every task goes through internal QA before reaching you.\nYou're never left chasing developers or fixing broken work.",
  },
  {
    question: "Can Boldteq handle large or ongoing projects?",
    answer:
      "Yes.\nBoldteq is built for continuous delivery — whether you're running multiple client projects or long-term builds.\nHigh-volume agencies use Boldteq as their permanent backend.",
  },
  {
    question: "Is Boldteq suitable for both early-stage and high-volume agencies?",
    answer:
      "Yes.\nEarly agencies use Boldteq to avoid hiring too early.\nScaling agencies use Boldteq to increase capacity without operational chaos.",
  },
];

