                  {(["starter", "growth", "pro"] as const).map((col) => {
                    const val = row[col];
                    return (
                      <td key={col} className="py-4 px-4 text-center text-[#374151]">
                        {val === false ? (
                          <CrossIcon />
                        ) : val === true ? (
                          <span className="text-[#019ae6] font-semibold">✓</span>
                        ) : (
                          val
                        )}
                      </td>
                    );
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Custom plan CTA */}
        <div className="mt-12 rounded-2xl bg-[#082753] p-8 md:p-12">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-center">
            <div>
              <h2 className="font-roobert text-[1.75rem] md:text-[2rem] font-semibold text-white mb-3 leading-tight">
                Need Something More Flexible?
              </h2>
              <p className="text-white/70 text-base mb-6">
                Create a custom subscription based on your workload, turnaround
                needs, and workflow.
              </p>
              <div className="flex flex-wrap gap-x-6 gap-y-3 mb-6">
                {[
                  "Flexible capacity",
                  "Custom turnaround",
                  "Multiple projects or brands",
                  "Simple monthly pricing",
                ].map((item) => (
                  <div key={item} className="flex items-center gap-2">
                    <Image
                      src="/images/webflow/Group-1.svg"
                      alt="Check Icon"
                      width={16}
                      height={16}
                    />
                    <span className="text-sm text-white/80">{item}</span>
                  </div>
                ))}
              </div>
              <Link
                href="/contact"
                className="inline-flex items-center justify-center rounded-full bg-gradient-to-r from-[#21cfff] to-[#019ae6] px-8 py-3 text-sm font-semibold text-white shadow-md transition-opacity hover:opacity-90"
              >
                Build Your Custom Plan
              </Link>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
